def number_to_words(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool) or not 0 <= n <= 999999:
        raise ValueError("n must be an integer between 0 and 999999")

    ones = [
        "zero", "one", "two", "three", "four",
        "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty",
        "fifty", "sixty", "seventy", "eighty", "ninety",
    ]

    def under_thousand(value: int) -> str:
        parts = []

        if value >= 100:
            parts.extend([ones[value // 100], "hundred"])
            value %= 100

        if value >= 20:
            tens_word = tens[value // 10]
            remainder = value % 10
            parts.append(
                f"{tens_word}-{ones[remainder]}" if remainder else tens_word
            )
        elif value > 0:
            parts.append(ones[value])

        return " ".join(parts)

    if n == 0:
        return "zero"

    parts = []

    if n >= 1000:
        parts.append(under_thousand(n // 1000))
        parts.append("thousand")
        n %= 1000

    if n:
        parts.append(under_thousand(n))

    return " ".join(parts)
